/* English text for data/qcm/apis.js (Maths, ECUE APIS: primitives, integrals and numerical sequences), merged by id
   over the French bank. Vocabulary of the English course “Primitive functions and integrals” and of the English
   Moodle: primitive, derivative, composite function, integral, area, rectangle method (lower / upper rectangles),
   bounds, Chasles’ relation, even / odd, mean value, linearity, integration by parts (IBP), change of variable, of
   class C¹, sequence, rank, bounded above / below, upper / lower bound, increasing / decreasing, monotonic,
   converges to, divergent, indeterminate forms, comparative growth, squeeze theorem, comparison theorem, geometric
   sequence, common ratio, arithmetic-geometric, fixed point, ratio criterion, adjacent sequences, subsequence,
   monotone convergence theorem, recursive sequence, negligible / equivalent / dominated. Decimal point. */
REV.i18n.topics({
  'apis-primitives': 'Course test · Usual and composite primitives',
  'apis-integrales': 'Course test · Integrals: areas, properties, computation',
  'apis-ipp': 'Course test · Integration by parts',
  'apis-cdv': 'Course test · Change of variable',
  'apis-suites': 'Course test · Sequences: bounds, monotonicity',
  'apis-limites': 'Course test · Limits of sequences',
  'apis-remarquables': 'Course test · Geometric sequences, remarkable examples',
  'apis-convergence': 'Final exam · Convergence theorems',
  'apis-recurrentes': 'Final exam · Recursive sequences',
  'apis-landau': 'Final exam · Landau comparisons'
});
(function () {
  var r = String.raw;
  REV.i18n.qcm({
    /* =============================================================== course 1: primitives */
    'apis-c1-01': { q: r`Let \(f\) be continuous on an interval \(I\). “\(F\) is a primitive of \(f\) on \(I\)” means:`,
      o: [r`\(F\) is differentiable on \(I\) and \(F' = f\)`, r`\(f\) is differentiable on \(I\) and \(f' = F\)`, r`\(F\) is continuous on \(I\) and \(F = f\)`, r`\(F(x) = f(x) + c\) with \(c\) a real number`],
      x: r`This is the definition from the course: \(\forall x \in I,\ F'(x) = f(x)\). Finding a primitive means differentiating “backwards”. The second answer swaps the roles of \(f\) and \(F\).` },
    'apis-c1-02': { q: r`If \(F\) is a primitive of \(f\) on an interval \(I\), then \(x \mapsto F(x) + 5\) is one too.`,
      x: r`True: \((F + 5)' = F' = f\). On an interval, all the primitives of \(f\) have the form \(F + c\), \(c\) a real number: there are infinitely many.` },
    'apis-c1-03': { q: r`Which primitive of \(x \mapsto \dfrac{1}{\sqrt{x}}\) on \(]0, +\infty[\) takes the value 3 at 4?`,
      o: [r`\(x \mapsto 2\sqrt{x} - 1\)`, r`\(x \mapsto 2\sqrt{x} + 3\)`, r`\(x \mapsto \sqrt{x} + 1\)`, r`\(x \mapsto 2\sqrt{x}\)`],
      x: r`The primitives are \(F(x) = 2\sqrt{x} + c\). \(F(4) = 4 + c = 3\) gives \(c = -1\). Imposing a value at one point fixes the constant: only one primitive is left (example from the course).` },
    'apis-c1-04': { q: r`A primitive of \(x \mapsto x^\alpha\), for a real number \(\alpha\) different from \(-1\), is:`,
      o: [r`\(x \mapsto \dfrac{x^{\alpha+1}}{\alpha+1}\)`, r`\(x \mapsto \alpha\, x^{\alpha-1}\)`, r`\(x \mapsto \dfrac{x^{\alpha+1}}{\alpha}\)`, r`\(x \mapsto \dfrac{x^{\alpha}}{\alpha+1}\)`],
      x: r`Increase the exponent by 1 and divide by the new exponent. \(\alpha x^{\alpha-1}\) is the derivative. The case \(\alpha = -1\) is separate: \(\frac{1}{x}\) has primitive \(\ln|x|\).` },
    'apis-c1-05': { q: r`A primitive of \(x \mapsto \sin(x)\) on \(\R\) is:`,
      o: [r`\(x \mapsto -\cos(x)\)`, r`\(x \mapsto \cos(x)\)`, r`\(x \mapsto -\sin(x)\)`, r`\(x \mapsto \tan(x)\)`],
      x: r`\((-\cos)' = \sin\). The minus sign goes with the primitive of sin and the derivative of cos: \((\cos)' = -\sin\), so \(\cos\) is a primitive of \(-\sin\).` },
    'apis-c1-06': { q: r`A primitive of \(x \mapsto \dfrac{1}{1 + x^2}\) on \(\R\) is:`,
      o: [r`\(x \mapsto \arctan(x)\)`, r`\(x \mapsto \ln(1 + x^2)\)`, r`\(x \mapsto \tan(x)\)`, r`\(x \mapsto -\dfrac{1}{1+x}\)`],
      x: r`\(\arctan'(x) = \frac{1}{1+x^2}\) (proved in Tutorial 3, exercise 1.1). \(\ln(1+x^2)\) has derivative \(\frac{2x}{1+x^2}\): it would need a \(2x\) in the numerator.` },
    'apis-c1-07': { q: r`A primitive of \(x \mapsto \dfrac{1}{x^2}\) on \(]0, +\infty[\) is:`,
      o: [r`\(x \mapsto -\dfrac{1}{x}\)`, r`\(x \mapsto \dfrac{1}{x}\)`, r`\(x \mapsto \ln(x^2)\)`, r`\(x \mapsto -\dfrac{2}{x^3}\)`],
      x: r`\(\frac{1}{x^2} = x^{-2}\): primitive \(\frac{x^{-1}}{-1} = -\frac{1}{x}\). \(-\frac{2}{x^3}\) is the derivative. \(\ln(x^2)\) has derivative \(\frac{2}{x}\).` },
    'apis-c1-08': { q: r`On an interval where the cosine does not vanish, a primitive of \(x \mapsto \dfrac{1}{\cos^2(x)} = 1 + \tan^2(x)\) is:`,
      o: [r`\(x \mapsto \tan(x)\)`, r`\(x \mapsto -\dfrac{1}{\cos(x)}\)`, r`\(x \mapsto \dfrac{\tan^3(x)}{3}\)`, r`\(x \mapsto \ln|\cos(x)|\)`],
      x: r`\(\tan' = \frac{1}{\cos^2} = 1 + \tan^2\): a line of the table you need to know. It is used in integration by parts (\(\int \frac{x}{\cos^2 x}\,dx\), Tutorial 3) and in changes of variable \(u = \tan t\).` },
    'apis-c1-09': { q: r`A primitive of \(x \mapsto x\sqrt{x}\) on \([0, +\infty[\) is:`,
      o: [r`\(x \mapsto \dfrac{2}{5}\,x^{5/2}\)`, r`\(x \mapsto \dfrac{x^2}{2}\cdot\dfrac{2}{3}x^{3/2}\)`, r`\(x \mapsto \dfrac{3}{2}\,x^{1/2}\)`, r`\(x \mapsto \dfrac{2}{3}\,x^{3/2}\)`],
      x: r`\(x\sqrt{x} = x^{3/2}\), with primitive \(\frac{x^{5/2}}{5/2} = \frac{2}{5}x^{5/2}\) (Tutorial 3, exercise 1.2). You never multiply the primitives of the two factors.` },
    'apis-c1-10': { q: r`A primitive of \(x \mapsto \dfrac{3}{x} - 5x + 6x^4\) on \(]0, +\infty[\) is:`,
      o: [r`\(x \mapsto 3\ln(x) - \dfrac{5}{2}x^2 + \dfrac{6}{5}x^5\)`, r`\(x \mapsto -\dfrac{3}{x^2} - 5 + 24x^3\)`, r`\(x \mapsto 3\ln(x) - 5x^2 + 6x^5\)`, r`\(x \mapsto \ln(3x) - \dfrac{5}{2}x^2 + \dfrac{6}{5}x^5\)`],
      x: r`Linearity: take a primitive of each term and keep the coefficients. The second answer is the derivative; the third forgets to divide by the new exponent.` },
    'apis-c1-11': { q: r`If \(F\) is a primitive of \(f\) and \(G\) a primitive of \(g\), then \(F \times G\) is a primitive of \(f \times g\).`,
      x: r`False: \((FG)' = fG + Fg\), not \(fg\). Primitives respect sums and multiplication by a real number, not products. For a product, look for a form \(u'\times g(u)\) or integrate by parts.` },
    'apis-c1-12': { q: r`A primitive of \(\dfrac{u'}{u}\), where \(u\) does not vanish on the interval, is:`,
      o: [r`\(\ln|u|\)`, r`\(-\dfrac{1}{u^2}\)`, r`\(\dfrac{u^2}{2}\)`, r`\(\ln(u')\)`],
      x: r`\((\ln|u|)' = \frac{u'}{u}\). The absolute value saves you from asking what the sign of \(u\) is.` },
    'apis-c1-13': { q: r`A primitive of \(x \mapsto e^{2x}\) on \(\R\) is:`,
      o: [r`\(x \mapsto \dfrac{e^{2x}}{2}\)`, r`\(x \mapsto 2e^{2x}\)`, r`\(x \mapsto e^{2x}\)`, r`\(x \mapsto \dfrac{e^{2x+1}}{2x+1}\)`],
      x: r`With \(u = 2x\): \(e^{2x} = \frac{1}{2}\,u' e^{u}\), with primitive \(\frac{1}{2}e^{u}\). You <b>divide</b> by 2; multiplying by 2 is differentiating.` },
    'apis-c1-14': { q: r`A primitive of \(u'\,u^\alpha\) (\(\alpha \neq -1\)) is:`,
      o: [r`\(\dfrac{u^{\alpha+1}}{\alpha+1}\)`, r`\(\dfrac{u^{\alpha+1}}{(\alpha+1)\,u'}\)`, r`\(\alpha\,u'\,u^{\alpha-1}\)`, r`\(u^{\alpha+1}\)`],
      x: r`\(\left(\frac{u^{\alpha+1}}{\alpha+1}\right)' = u' u^\alpha\). The \(u'\) is “used up”: it does not remain in the primitive.` },
    'apis-c1-15': { q: r`A primitive of \(\dfrac{u'}{\sqrt{u}}\) (with \(u \gt 0\)) is:`,
      o: [r`\(2\sqrt{u}\)`, r`\(\sqrt{u}\)`, r`\(\dfrac{1}{2\sqrt{u}}\)`, r`\(\ln(\sqrt{u})\)`],
      x: r`\((\sqrt{u})' = \frac{u'}{2\sqrt{u}}\), so \(\frac{u'}{\sqrt{u}}\) has primitive \(2\sqrt{u}\). The table in the course gives the line \(\frac{u'}{2\sqrt{u}} \to \sqrt{u}\): watch the 2.` },
    'apis-c1-16': { q: r`A primitive of \(x \mapsto \cos(3x)\) on \(\R\) is:`,
      o: [r`\(x \mapsto \dfrac{\sin(3x)}{3}\)`, r`\(x \mapsto 3\sin(3x)\)`, r`\(x \mapsto -\dfrac{\sin(3x)}{3}\)`, r`\(x \mapsto \sin(3x)\)`],
      x: r`\(u = 3x\), \(u' = 3\): \(\cos(3x) = \frac{1}{3}u'\cos(u)\), with primitive \(\frac{1}{3}\sin(u)\). Check by differentiating: \(\left(\frac{\sin(3x)}{3}\right)' = \cos(3x)\).` },
    'apis-c1-17': { q: r`A primitive of \(x \mapsto \tan(x)\) on \(\left]-\frac{\pi}{2}, \frac{\pi}{2}\right[\) is:`,
      o: [r`\(x \mapsto -\ln(\cos(x))\)`, r`\(x \mapsto \ln(\cos(x))\)`, r`\(x \mapsto \dfrac{1}{\cos^2(x)}\)`, r`\(x \mapsto \ln(\sin(x))\)`],
      x: r`\(\tan = \frac{\sin}{\cos} = -\frac{u'}{u}\) with \(u = \cos\), \(u' = -\sin\). Primitive: \(-\ln|\cos x|\) (Moodle model exercise, Tutorial 3 ex. 1.2). \(\frac{1}{\cos^2}\) is the derivative of tan.` },
    'apis-c1-18': { q: r`A primitive of \(x \mapsto x\,e^{x^2}\) on \(\R\) is:`,
      o: [r`\(x \mapsto \dfrac{e^{x^2}}{2}\)`, r`\(x \mapsto \dfrac{x^2}{2}\,e^{x^2}\)`, r`\(x \mapsto e^{x^2}\)`, r`\(x \mapsto 2x\,e^{x^2}\)`],
      x: r`\(u = x^2\), \(u' = 2x\): \(x e^{x^2} = \frac{1}{2}u'e^{u}\). A factor 2 was missing: make it appear and compensate with \(\frac{1}{2}\) (practice from the course).` },
    'apis-c1-19': { q: r`A primitive of \(x \mapsto \dfrac{4x + 8}{\sqrt{x^2 + 4x + 1}}\) is (Tutorial 3):`,
      o: [r`\(x \mapsto 4\sqrt{x^2 + 4x + 1}\)`, r`\(x \mapsto 2\sqrt{x^2 + 4x + 1}\)`, r`\(x \mapsto \ln(x^2 + 4x + 1)\)`, r`\(x \mapsto \dfrac{2x^2 + 8x}{\sqrt{x^2 + 4x + 1}}\)`],
      x: r`\(u = x^2 + 4x + 1\), \(u' = 2x + 4\): the numerator is \(2u'\). \(\frac{2u'}{\sqrt{u}}\) has primitive \(2 \times 2\sqrt{u} = 4\sqrt{u}\).` },
    'apis-c1-20': { q: r`Can you write a primitive of \(x \mapsto e^{x^2}\) by recognising a form \(u'e^{u}\)?`,
      o: [r`No: the factor \(u' = 2x\) is missing, and it is not a constant`, r`Yes: \(x \mapsto \dfrac{e^{x^2}}{2x}\)`, r`Yes: \(x \mapsto e^{x^2}\)`, r`Yes: \(x \mapsto \dfrac{e^{x^3}}{3}\)`],
      x: r`You can only compensate for a missing <b>constant</b>. \(\frac{e^{x^2}}{2x}\) does not work: its derivative is not \(e^{x^2}\) (differentiate a quotient). This is the question from Tutorial 3: “can you compute a primitive of \(e^{2x}\)? of \(e^{x^2}\)?”. The function has primitives (it is continuous), but they cannot be written with the usual functions.` },

    /* =============================================================== course 2: integrals */
    'apis-c2-01': { q: r`For \(f\) continuous and <b>positive</b> on \([a, b]\), \(\displaystyle\int_a^b f(x)\,dx\) is:`,
      o: [r`the area, in area units, between the curve of \(f\), the x-axis and the lines \(x = a\) and \(x = b\)`, r`the slope of the curve of \(f\) between \(a\) and \(b\)`, r`the length of the curve of \(f\) between \(a\) and \(b\)`, r`the value \(f(b) - f(a)\)`],
      x: r`This is the definition from the course. \(f(b) - f(a)\) would be the integral of \(f'\), not of \(f\).` },
    'apis-c2-02': { q: r`Using areas (a rectangle and a triangle), what is \(\displaystyle\int_0^2 (x + 1)\,dx\)?`,
      x: r`Rectangle \(2 \times 1 = 2\), triangle \(\frac{2 \times 2}{2} = 2\): total 4 (example from the course). Check: \(\left[\frac{x^2}{2} + x\right]_0^2 = 2 + 2 = 4\).` },
    'apis-c2-03': { q: r`If \(f\) is continuous and <b>negative</b> on \([a, b]\), and \(\mathcal{A}\) is the area between its curve and the x-axis, then \(\displaystyle\int_a^b f(x)\,dx\) equals:`,
      o: [r`\(-\mathcal{A}\)`, r`\(\mathcal{A}\)`, r`0`, r`\(|\mathcal{A}|^2\)`],
      x: r`An area is positive; the integral of a negative function is the opposite of the area. For a function of any sign, the pieces above the axis count positively and those below count negatively.` },
    'apis-c2-04': { q: r`Using an area, what is \(\displaystyle\int_2^6 (-x + 2)\,dx\)?`,
      x: r`On \([2, 6]\), \(-x + 2 \leq 0\): the curve is below the axis and forms a triangle with base 4 and height 4, of area 8. The integral is \(-8\) (example from the course).` },
    'apis-c2-05': { q: r`Using areas, what is \(\displaystyle\int_{-2}^{6} x\,dx\) (Tutorial 3, exercise 3.6)?`,
      x: r`Triangle below the axis on \([-2, 0]\): area 2, counted as \(-2\). Triangle above the axis on \([0, 6]\): area 18. Total \(18 - 2 = 16\).` },
    'apis-c2-06': { q: r`What is \(\displaystyle\int_2^5 (3 - x)\,dx\)?`,
      o: [r`\(-\dfrac{3}{2}\)`, r`\(\dfrac{5}{2}\)`, r`\(\dfrac{3}{2}\)`, r`\(-\dfrac{5}{2}\)`],
      x: r`Small triangle above the axis on \([2, 3]\), of area \(\frac{1}{2}\); large triangle below on \([3, 5]\), of area 2. Integral: \(\frac{1}{2} - 2 = -\frac{3}{2}\). \(\frac{5}{2}\) is the total area, ignoring the sign.` },
    'apis-c2-07': { q: r`You bound \(I = \displaystyle\int_0^1 x^2\,dx\) with the rectangle method using 5 intervals of length 0.2. You get:`,
      o: [r`\(0.24 \leq I \leq 0.44\)`, r`\(0.2 \leq I \leq 0.4\)`, r`\(0.285 \leq I \leq 0.385\)`, r`\(0.30 \leq I \leq 0.36\)`],
      x: r`Lower rectangles: \(0.2 \times (0 + 0.04 + 0.16 + 0.36 + 0.64) = 0.24\). Upper: \(0.2 \times (0.04 + 0.16 + 0.36 + 0.64 + 1) = 0.44\). The bounds \(0.285 \leq I \leq 0.385\) are those for 10 intervals. Exact value: \(\frac{1}{3}\).` },
    'apis-c2-08': { q: r`For a positive and <b>increasing</b> function, the rectangles whose height is taken at the left end of each interval give an underestimate of the integral.`,
      x: r`True: if \(f\) is increasing, its smallest value on each interval is at the left end, so these rectangles lie under the curve. For a decreasing function it is the opposite: the left end gives an overestimate.` },
    'apis-c2-09': { q: r`You bound \(\displaystyle\int_0^4 \sqrt{x}\,dx\) with two series of four rectangles of width 1 (Tutorial 3, exercise 2.3). The bounds are:`,
      o: [r`\(1 + \sqrt{2} + \sqrt{3} \leq I \leq 3 + \sqrt{2} + \sqrt{3}\)`, r`\(\sqrt{2} + \sqrt{3} \leq I \leq 1 + \sqrt{2} + \sqrt{3}\)`, r`\(1 + \sqrt{2} + \sqrt{3} \leq I \leq 4\)`, r`\(4 \leq I \leq 8\)`],
      x: r`Lower rectangles: \(\sqrt{0} + \sqrt{1} + \sqrt{2} + \sqrt{3} \approx 4.15\). Upper: \(\sqrt{1} + \sqrt{2} + \sqrt{3} + \sqrt{4} \approx 6.15\). The gap is \(f(4) - f(0) = 2\). Exact value: \(\frac{16}{3} \approx 5.33\).` },
    'apis-c2-10': { q: r`Chasles’ relation, for \(f\) continuous on \([a, b]\) and \(c \in [a, b]\), is written:`,
      o: [r`\(\displaystyle\int_a^b f = \int_a^c f + \int_c^b f\)`, r`\(\displaystyle\int_a^b f = \int_a^c f \times \int_c^b f\)`, r`\(\displaystyle\int_a^b f = \int_a^c f - \int_c^b f\)`, r`\(\displaystyle\int_a^b f = \int_c^a f + \int_c^b f\)`],
      x: r`You split the interval in two and add the two integrals. It is what you use for a piecewise-defined function (Tutorial 3, exercises 3.7 and 3.8).` },
    'apis-c2-11': { q: r`What is \(\displaystyle\int_{-3}^{3} |x|\,dx\)?`,
      x: r`\(x \mapsto |x|\) is even: the integral equals \(2\displaystyle\int_0^3 x\,dx = 2 \times \frac{9}{2} = 9\). The course handout writes “\(2 \times 9 = 18\)”: a typo, the area of the right-hand triangle is indeed \(\frac{9}{2}\).` },
    'apis-c2-12': { q: r`For \(f\) continuous and <b>odd</b> on \([-a, a]\), \(\displaystyle\int_{-a}^{a} f(x)\,dx\) equals:`,
      o: [r`0`, r`\(2\displaystyle\int_0^a f(x)\,dx\)`, r`\(f(a) - f(-a)\)`, r`\(2f(a)\)`],
      x: r`The areas on either side of 0 cancel: for example \(\displaystyle\int_{-\pi}^{\pi} \sin(x)\,dx = 0\). The doubling, \(2\int_0^a f\), is the property of <b>even</b> functions.` },
    'apis-c2-13': { q: r`When you swap the bounds: \(\displaystyle\int_b^a f(t)\,dt = \)`,
      o: [r`\(-\displaystyle\int_a^b f(t)\,dt\)`, r`\(\displaystyle\int_a^b f(t)\,dt\)`, r`\(\displaystyle\int_a^b f(-t)\,dt\)`, r`0`],
      x: r`\(F(a) - F(b) = -(F(b) - F(a))\). Useful after a change of variable that reverses the order of the bounds.` },
    'apis-c2-14': { q: r`If \(F\) is a primitive of \(f\), continuous on \([a, b]\), then \(\displaystyle\int_a^b f(x)\,dx = \)`,
      o: [r`\(F(b) - F(a)\)`, r`\(F(a) - F(b)\)`, r`\(f(b) - f(a)\)`, r`\(F(b) + F(a)\)`],
      x: r`We write \(\left[F(x)\right]_a^b = F(b) - F(a)\): the upper bound first. The result does not depend on the primitive chosen: the constant cancels.` },
    'apis-c2-15': { q: r`Fundamental theorem: for \(f\) continuous on \([a, b]\), the function \(F : x \mapsto \displaystyle\int_a^x f(t)\,dt\) is:`,
      o: [r`the primitive of \(f\) that vanishes at \(a\)`, r`the derivative of \(f\)`, r`a primitive of \(f\) that vanishes at \(b\)`, r`a constant function`],
      x: r`\(F' = f\) and \(F(a) = \displaystyle\int_a^a f = 0\). This theorem is what links computing an area to computing a primitive.` },
    'apis-c2-16': { q: r`What is \(\displaystyle\int_0^4 x^2\,dx\)?`,
      o: [r`\(\dfrac{64}{3}\)`, r`16`, r`64`, r`8`],
      x: r`\(\left[\frac{x^3}{3}\right]_0^4 = \frac{64}{3}\). 16 is \(f(4)\), 8 is the derivative at 4.` },
    'apis-c2-17': { q: r`What is \(\displaystyle\int_0^4 \frac{2x}{x^2 + 1}\,dx\)?`,
      o: [r`\(\ln(17)\)`, r`\(\ln(16)\)`, r`\(\dfrac{8}{17}\)`, r`\(2\ln(17)\)`],
      x: r`Form \(\frac{u'}{u}\) with \(u = x^2 + 1\): \(\left[\ln(x^2 + 1)\right]_0^4 = \ln(17) - \ln(1) = \ln(17)\) (example from the course).` },
    'apis-c2-18': { q: r`If \(f(x) \leq g(x)\) for all \(x\) in \([a, b]\) (with \(a \lt b\)), then:`,
      o: [r`\(\displaystyle\int_a^b f(x)\,dx \leq \int_a^b g(x)\,dx\)`, r`\(\displaystyle\int_a^b f(x)\,dx \geq \int_a^b g(x)\,dx\)`, r`\(\displaystyle\int_a^b f(x)\,dx = \int_a^b g(x)\,dx\)`, r`nothing can be said`],
      x: r`The integral preserves order (the integral is increasing), provided the bounds are in the right order. In particular, a positive function has a positive integral.` },
    'apis-c2-19': { q: r`Without computing a primitive, what bounds do you get for \(I = \displaystyle\int_0^1 e^{x^2}\,dx\)?`,
      o: [r`\(1 \leq I \leq e\)`, r`\(0 \leq I \leq 1\)`, r`\(e \leq I \leq e^2\)`, r`\(I = e - 1\)`],
      x: r`On \([0, 1]\), \(x \mapsto e^{x^2}\) is increasing: \(1 \leq e^{x^2} \leq e\). Integrating over an interval of length 1: \(1 \leq I \leq e\) (example from the course). \(e - 1\) is the integral of \(e^x\), not of \(e^{x^2}\).` },
    'apis-c2-20': { q: r`The mean value of a function \(f\) continuous on \([a, b]\) is:`,
      o: [r`\(\dfrac{1}{b - a}\displaystyle\int_a^b f(x)\,dx\)`, r`\(\dfrac{f(a) + f(b)}{2}\)`, r`\((b - a)\displaystyle\int_a^b f(x)\,dx\)`, r`\(\dfrac{f(b) - f(a)}{b - a}\)`],
      x: r`It is the height of the rectangle with base \([a, b]\) that has the same area as the region under the curve. Example from the course: the mean value of \(e^x\) on \([0, 1]\) is \(\frac{e - 1}{1 - 0} = e - 1\).` },

    /* =============================================================== course 3: IBP and change of variable */
    'apis-c3-01': { q: r`The integration by parts formula, for \(u\) and \(v\) of class \(\mathcal{C}^1\) on \([a, b]\), is written:`,
      o: [r`\(\displaystyle\int_a^b u(x)v'(x)\,dx = \left[u(x)v(x)\right]_a^b - \int_a^b u'(x)v(x)\,dx\)`, r`\(\displaystyle\int_a^b u(x)v'(x)\,dx = \left[u(x)v(x)\right]_a^b + \int_a^b u'(x)v(x)\,dx\)`, r`\(\displaystyle\int_a^b u(x)v'(x)\,dx = \left[u'(x)v(x)\right]_a^b - \int_a^b u(x)v(x)\,dx\)`, r`\(\displaystyle\int_a^b u(x)v(x)\,dx = \int_a^b u(x)\,dx \times \int_a^b v(x)\,dx\)`],
      x: r`The bracket applies to the product \(uv\), then you subtract the integral where the derivative has moved to the other factor. The October 2022 course test asked you to state it “without forgetting its hypotheses”: \(u\) and \(v\) of class \(\mathcal{C}^1\) on \([a, b]\).` },
    'apis-c3-02': { q: r`The proof of the integration by parts formula starts from:`,
      o: [r`\((uv)' = u'v + uv'\), which you integrate between \(a\) and \(b\)`, r`\((u \circ v)' = (u' \circ v) \times v'\)`, r`Chasles’ relation`, r`the rectangle method`],
      x: r`\(uv\) is a primitive of \(u'v + uv'\): \(\left[uv\right]_a^b = \displaystyle\int_a^b u'v + \int_a^b uv'\) by linearity, and you isolate \(\displaystyle\int_a^b uv'\). This proof was asked in the October 2022 course test.` },
    'apis-c3-03': { q: r`“\(u\) is of class \(\mathcal{C}^1\) on \([a, b]\)” means:`,
      o: [r`\(u\) is differentiable on \([a, b]\) and \(u'\) is continuous`, r`\(u\) is continuous on \([a, b]\)`, r`\(u\) is positive on \([a, b]\)`, r`\(u\) is a primitive of a differentiable function`],
      x: r`Differentiable with a continuous derivative: this is needed so that \(u'v\) and \(uv'\) are continuous, hence integrable. It is the hypothesis of the formula.` },
    'apis-c3-04': { q: r`To compute \(\displaystyle\int_0^1 (2x + 3)e^{3x}\,dx\) by parts, you set:`,
      o: [r`\(u(x) = 2x + 3\) and \(v'(x) = e^{3x}\)`, r`\(u(x) = e^{3x}\) and \(v'(x) = 2x + 3\)`, r`\(u(x) = 2x\) and \(v'(x) = 3e^{3x}\)`, r`\(u(x) = (2x+3)e^{3x}\) and \(v'(x) = 1\)`],
      x: r`You differentiate the polynomial (its degree drops) and integrate the exponential (it stays an exponential). The other choice would raise the degree: the integral would get more complicated.` },
    'apis-c3-05': { q: r`To compute \(\displaystyle\int_1^e \ln(x)\,dx\) by parts, you set:`,
      o: [r`\(u(x) = \ln(x)\) and \(v'(x) = 1\)`, r`\(u(x) = 1\) and \(v'(x) = \ln(x)\)`, r`\(u(x) = x\) and \(v'(x) = \ln(x)\)`, r`you cannot: there is only one factor`],
      x: r`Write \(\ln(x) = \ln(x) \times 1\): you differentiate the logarithm (\(u' = \frac{1}{x}\)) and integrate 1 (\(v = x\)). Then \(\left[x\ln x\right]_1^e - \displaystyle\int_1^e 1\,dx = e - (e - 1) = 1\).` },
    'apis-c3-06': { q: r`What is \(\displaystyle\int_0^1 (3x + 1)e^{2x}\,dx\) (January 2024 exam)?`,
      o: [r`\(\dfrac{5e^2 + 1}{4}\)`, r`\(2e^2 - \dfrac{1}{2}\)`, r`\(\dfrac{5e^2 - 1}{4}\)`, r`\(\dfrac{3e^2}{4}\)`],
      x: r`\(u = 3x + 1\), \(v' = e^{2x}\), \(v = \frac{e^{2x}}{2}\): \(\left[(3x+1)\frac{e^{2x}}{2}\right]_0^1 - \displaystyle\int_0^1 \frac{3}{2}e^{2x}\,dx = 2e^2 - \frac{1}{2} - \frac{3}{4}(e^2 - 1) = \frac{5e^2 + 1}{4}\). The answer \(2e^2 - \frac{1}{2}\) stops at the bracket.` },
    'apis-c3-07': { q: r`What is \(\displaystyle\int_0^{\pi} x^2\cos(x)\,dx\) (Moodle model exercise)?`,
      o: [r`\(-2\pi\)`, r`\(2\pi\)`, r`\(\pi^2\)`, r`0`],
      x: r`First integration by parts: \(\left[x^2\sin x\right]_0^\pi - \displaystyle\int_0^\pi 2x\sin x\,dx = -2\int_0^\pi x\sin x\,dx\). Second: \(\displaystyle\int_0^\pi x\sin x\,dx = \left[-x\cos x\right]_0^\pi + \int_0^\pi \cos x\,dx = \pi\). Result: \(-2\pi\).` },
    'apis-c3-08': { q: r`For \(M = \displaystyle\int_0^\pi e^x\sin(x)\,dx\) (Tutorial 3), two integrations by parts give \(M = e^\pi + 1 - M\). So:`,
      o: [r`\(M = \dfrac{e^\pi + 1}{2}\)`, r`\(M = e^\pi + 1\)`, r`we are going round in circles: the method fails`, r`\(M = 0\)`],
      x: r`Getting back the starting integral is not a failure: you obtain an equation with unknown \(M\), \(2M = e^\pi + 1\). You must keep the same choice in both steps (differentiate the trigonometric function twice, or the exponential twice).` },
    'apis-c3-09': { q: r`For \(I_n = \displaystyle\int_0^1 t^n e^{-t}\,dt\), one integration by parts gives (Moodle model exercise):`,
      o: [r`\(I_{n+1} = (n+1)I_n - \dfrac{1}{e}\)`, r`\(I_{n+1} = (n+1)I_n + \dfrac{1}{e}\)`, r`\(I_{n+1} = nI_n - \dfrac{1}{e}\)`, r`\(I_{n+1} = I_n - \dfrac{n+1}{e}\)`],
      x: r`\(u = t^{n+1}\), \(v' = e^{-t}\), \(v = -e^{-t}\): \(I_{n+1} = \left[-t^{n+1}e^{-t}\right]_0^1 + (n+1)\displaystyle\int_0^1 t^n e^{-t}\,dt = -e^{-1} + (n+1)I_n\). Check: \(I_0 = 1 - \frac{1}{e}\), \(I_1 = 1 - \frac{2}{e}\).` },
    'apis-c3-10': { q: r`In a change of variable \(t = \varphi(x)\), the differential element becomes:`,
      o: [r`\(dt = \varphi'(x)\,dx\)`, r`\(dt = dx\)`, r`\(dt = \varphi(x)\,dx\)`, r`\(dx = \varphi'(x)\,dt\)`],
      x: r`You differentiate the relation \(t = \varphi(x)\). Forgetting this factor is the most common mistake: replacing \(dx\) by \(dt\) with no other change is wrong as soon as \(\varphi' \neq 1\).` },
    'apis-c3-11': { q: r`In \(\displaystyle\int_0^1 \frac{e^x}{e^{2x} + 1}\,dx\), you set \(t = e^x\). The new bounds are:`,
      o: [r`1 and \(e\)`, r`0 and 1`, r`0 and \(e\)`, r`1 and \(e^2\)`],
      x: r`\(x = 0\) gives \(t = e^0 = 1\); \(x = 1\) gives \(t = e\). The bounds are those of the <b>new</b> variable: keeping 0 and 1 is a classic mistake.` },
    'apis-c3-12': { q: r`With \(t = e^x\), \(\displaystyle\int_0^1 \frac{e^x}{e^{2x} + 1}\,dx\) becomes:`,
      o: [r`\(\displaystyle\int_1^e \frac{dt}{t^2 + 1}\)`, r`\(\displaystyle\int_1^e \frac{t}{t^2 + 1}\,dt\)`, r`\(\displaystyle\int_0^1 \frac{dt}{t^2 + 1}\)`, r`\(\displaystyle\int_1^e \frac{dt}{2t + 1}\)`],
      x: r`\(dt = e^x\,dx\): the \(e^x\) in the numerator is absorbed by \(dt\); \(e^{2x} = t^2\). You recognise the derivative of arctan: result \(\arctan(e) - \frac{\pi}{4}\) (Moodle model exercise).` },
    'apis-c3-13': { q: r`What is \(K = \displaystyle\int_0^{\ln(\sqrt{3})} \frac{dt}{e^{-t} + e^{t}}\), computed by setting \(x = e^t\) (Tutorial 3 and January 2024 exam)?`,
      o: [r`\(\dfrac{\pi}{12}\)`, r`\(\dfrac{\pi}{3}\)`, r`\(\dfrac{\pi}{4}\)`, r`\(\ln(\sqrt{3})\)`],
      x: r`\(dx = e^t\,dt\), so \(dt = \frac{dx}{x}\); \(\frac{1}{e^{-t} + e^t} = \frac{x}{1 + x^2}\). \(K = \displaystyle\int_1^{\sqrt{3}} \frac{dx}{1 + x^2} = \arctan(\sqrt{3}) - \arctan(1) = \frac{\pi}{3} - \frac{\pi}{4} = \frac{\pi}{12}\). \(\frac{\pi}{3}\) forgets the lower bound.` },
    'apis-c3-14': { q: r`If \(F\) is a primitive of \(f\), a primitive of \((f \circ \varphi)\times\varphi'\) is:`,
      o: [r`\(F \circ \varphi\)`, r`\(F \circ f\)`, r`\(F \times \varphi\)`, r`\(f \circ \varphi\)`],
      x: r`\((F \circ \varphi)' = (F' \circ \varphi) \times \varphi' = (f \circ \varphi)\times\varphi'\). The sheet wrongly writes \(F \circ f\). It is the form \(u' \times g(u)\) from course 1, seen differently.` },

    /* =============================================================== course 4: sequences */
    'apis-c4-01': { q: r`A real sequence is:`,
      o: [r`a map from \(\N\) to \(\R\)`, r`a map from \(\R\) to \(\N\)`, r`a finite list of real numbers`, r`a continuous function on \(\R\)`],
      x: r`\(u : \N \to \R\), \(n \mapsto u_n\). \(u_n\) is the term of rank \(n\); the sequence is written \((u_n)\) or \((u_n)_{n \in \N}\), with the parentheses.` },
    'apis-c4-02': { q: r`The sequence defined by \(u_0 = 0\) and \(u_{n+1} = \sqrt{1 + u_n}\) is defined:`,
      o: [r`recursively: each term is computed from the previous one`, r`explicitly: \(u_n\) is given as a function of \(n\)`, r`by a sum`, r`only for even \(n\)`],
      x: r`An explicit definition would give \(u_n = f(n)\). Here you need \(u_n\) to compute \(u_{n+1}\): \(u_1 = 1\), \(u_2 = \sqrt{2}\)… You also have to check that every term exists (Moodle model exercise).` },
    'apis-c4-03': { q: r`“\((u_n)\) is bounded above” is written with quantifiers as:`,
      o: [r`\(\exists M \in \R,\ \forall n \in \N,\ u_n \leq M\)`, r`\(\forall n \in \N,\ \exists M \in \R,\ u_n \leq M\)`, r`\(\forall M \in \R,\ \exists n \in \N,\ u_n \leq M\)`, r`\(\exists M \in \R,\ \exists n \in \N,\ u_n \leq M\)`],
      x: r`The <b>same</b> \(M\) must work for every \(n\): \(\exists M\) comes first. The second sentence is true for every sequence (take \(M = u_n\)): it says nothing.` },
    'apis-c4-04': { q: r`“\((u_n)\) is bounded” is equivalent to:`,
      o: [r`\(\exists M \in \R,\ \forall n \in \N,\ |u_n| \leq M\)`, r`\(\forall n \in \N,\ \exists M \in \R,\ |u_n| \leq M\)`, r`\(\exists M \in \R,\ \forall n \in \N,\ u_n \leq M\)`, r`\((u_n)\) converges`],
      x: r`Bounded = bounded above and below, which is equivalent to \(|u_n| \leq M\) (proof to know, with \(M = \max(|m|, |K|)\)). The third answer only says “bounded above”. A bounded sequence does not necessarily converge: \(((-1)^n)\).` },
    'apis-c4-05': { q: r`The negation of “\((u_n)\) is bounded above” is:`,
      o: [r`\(\forall M \in \R,\ \exists n \in \N,\ u_n \gt M\)`, r`\(\exists M \in \R,\ \forall n \in \N,\ u_n \gt M\)`, r`\(\forall M \in \R,\ \forall n \in \N,\ u_n \gt M\)`, r`\(\exists M \in \R,\ \exists n \in \N,\ u_n \geq M\)`],
      x: r`You swap \(\exists\) and \(\forall\) and negate the inequality: whatever candidate \(M\) you take, some term exceeds it. The second answer says “strictly bounded below”. Question from the January 2020 exam (“\((u_n)\) is not bounded”).` },
    'apis-c4-06': { q: r`The sequence \(u_n = \dfrac{n}{n+3}\) (\(n \in \N\)) is:`,
      o: [r`bounded below by 0 and bounded above by 1`, r`bounded below by 0, not bounded above`, r`bounded above by 1, not bounded below`, r`not bounded`],
      x: r`\(n \geq 0\) and \(n + 3 \gt 0\): \(u_n \geq 0\). \(n \lt n + 3\): \(u_n \lt 1\). The sequence is bounded (Moodle model exercise). 1 is an upper bound, never reached.` },
    'apis-c4-07': { q: r`“\((u_n)\) is increasing” is written:`,
      o: [r`\(\forall n \in \N,\ u_{n+1} \geq u_n\)`, r`\(\exists n \in \N,\ u_{n+1} \geq u_n\)`, r`\(\forall n \in \N,\ u_n \geq 0\)`, r`\(\forall n \in \N,\ u_{n+1} \gt u_n\)`],
      x: r`Non-strict inequality, for all \(n\). With the strict inequality, the sequence is <b>strictly</b> increasing. “Monotonic” means increasing or decreasing. Definition asked in the 2022 and 2023 course tests.` },
    'apis-c4-08': { q: r`To study the monotonicity of \((u_n)\) with the ratio \(\dfrac{u_{n+1}}{u_n}\) compared to 1, you need:`,
      o: [r`all terms to be strictly positive`, r`the sequence to be geometric`, r`the sequence to be bounded`, r`\(u_0 = 1\)`],
      x: r`If \(u_n \gt 0\), \(\frac{u_{n+1}}{u_n} \geq 1 \iff u_{n+1} \geq u_n\). With negative terms, multiplying by \(u_n\) reverses the inequality. Otherwise, study the sign of \(u_{n+1} - u_n\), which always works.` },
    'apis-c4-09': { q: r`For \(u_n = \dfrac{n}{n+3}\), \(u_{n+1} - u_n\) equals:`,
      o: [r`\(\dfrac{3}{(n+3)(n+4)}\), so the sequence is strictly increasing`, r`\(\dfrac{-3}{(n+3)(n+4)}\), so the sequence is strictly decreasing`, r`\(\dfrac{1}{n+4}\), so the sequence is strictly increasing`, r`0, so the sequence is constant`],
      x: r`\(\frac{n+1}{n+4} - \frac{n}{n+3} = \frac{(n+1)(n+3) - n(n+4)}{(n+3)(n+4)} = \frac{3}{(n+3)(n+4)} \gt 0\) (Moodle answer key).` },
    'apis-c4-10': { q: r`Which of these sequences is neither increasing nor decreasing?`,
      o: [r`\(u_n = (-1)^n\)`, r`\(u_n = n^2\)`, r`\(u_n = \dfrac{1}{n+1}\)`, r`\(u_n = 3\)`],
      x: r`\(1, -1, 1, -1\ldots\) goes up and down. \((n^2)\) is increasing, \(\left(\frac{1}{n+1}\right)\) is decreasing, a constant sequence is both. Example asked in the November 2023 course test.` },
    'apis-c4-11': { q: r`A stationary sequence is a sequence that is:`,
      o: [r`constant from some rank onwards`, r`bounded`, r`periodic`, r`tending to 0`],
      x: r`Summary sheet: \(\exists N \in \N,\ \forall n \geq N,\ u_n = u_N\). A constant sequence is stationary; the converse is false.` },
    'apis-c4-12': { q: r`“\((u_n)\) converges to \(\ell\)” is written:`,
      o: [r`\(\forall \varepsilon \gt 0,\ \exists N \in \N,\ \forall n \geq N,\ |u_n - \ell| \lt \varepsilon\)`, r`\(\exists \varepsilon \gt 0,\ \forall N \in \N,\ \forall n \geq N,\ |u_n - \ell| \lt \varepsilon\)`, r`\(\exists N \in \N,\ \forall \varepsilon \gt 0,\ \forall n \geq N,\ |u_n - \ell| \lt \varepsilon\)`, r`\(\forall \varepsilon \gt 0,\ \forall n \in \N,\ |u_n - \ell| \lt \varepsilon\)`],
      x: r`For every precision \(\varepsilon\), there is a rank (depending on \(\varepsilon\)) from which all the terms lie in \(]\ell - \varepsilon, \ell + \varepsilon[\). The third sentence, with \(N\) before \(\varepsilon\), says the sequence is stationary. Definition asked in the January 2023 exam.` },
    'apis-c4-13': { q: r`“\((u_n)\) tends to \(+\infty\)” is written:`,
      o: [r`\(\forall A \in \R,\ \exists N \in \N,\ \forall n \geq N,\ u_n \gt A\)`, r`\(\exists A \in \R,\ \forall n \in \N,\ u_n \gt A\)`, r`\(\forall A \in \R,\ \exists n \in \N,\ u_n \gt A\)`, r`\(\forall n \in \N,\ u_{n+1} \gt u_n\)`],
      x: r`Every threshold \(A\) is exceeded <b>from some rank onwards</b>, and for good. The third sentence only says “not bounded above”: \(u_n = n\) if \(n\) is even, 0 otherwise, satisfies it without tending to \(+\infty\). The second says “bounded below”.` },
    'apis-c4-14': { q: r`A divergent sequence is a sequence that:`,
      o: [r`does not converge: it tends to \(\pm\infty\) or has no limit`, r`tends to \(+\infty\)`, r`is not bounded`, r`is decreasing`],
      x: r`“Divergent” is the negation of “convergent”. \(((-1)^n)\) diverges while staying bounded; \((n)\) diverges to \(+\infty\).` },
    'apis-c4-15': { q: r`To show with the definition that \(u_n = \dfrac{1}{n^2}\) converges to 0, for a given \(\varepsilon \gt 0\) you can take:`,
      o: [r`an integer \(N \geq \dfrac{1}{\sqrt{\varepsilon}}\)`, r`\(N = \varepsilon\)`, r`\(N = \dfrac{1}{\varepsilon^2}\) in all cases`, r`\(N = 0\)`],
      x: r`\(\frac{1}{n^2} \leq \varepsilon \iff n \geq \frac{1}{\sqrt{\varepsilon}}\). Any integer \(N\) above \(\frac{1}{\sqrt{\varepsilon}}\) works, for example \(E\!\left(\frac{1}{\sqrt{\varepsilon}}\right) + 1\) (Moodle answer key).` },
    'apis-c4-16': { q: r`What is \(\displaystyle\lim_{n \to +\infty} \frac{2 + n - n^2}{n^2 + 3n + 4}\)?`,
      o: [r`\(-1\)`, r`\(1\)`, r`\(\dfrac{1}{2}\)`, r`\(-\infty\)`],
      x: r`Factor \(n^2\) out of the numerator and the denominator: \(\frac{\frac{2}{n^2} + \frac{1}{n} - 1}{1 + \frac{3}{n} + \frac{4}{n^2}} \to \frac{-1}{1} = -1\) (Moodle model exercise). The quotient of the highest-degree terms gives the result.` },
    'apis-c4-17': { q: r`Which of these situations is an indeterminate form?`,
      o: [r`\(u_n \to +\infty\) and \(v_n \to -\infty\), limit of \(u_n + v_n\)`, r`\(u_n \to +\infty\) and \(v_n \to +\infty\), limit of \(u_n + v_n\)`, r`\(u_n \to 2\) and \(v_n \to +\infty\), limit of \(u_n v_n\)`, r`\(u_n \to 0\) and \(v_n \to 3\), limit of \(u_n v_n\)`],
      x: r`“\(+\infty - \infty\)”: nothing can be said without transforming the expression. The four indeterminate forms: \(\infty - \infty\), \(0 \times \infty\), \(\frac{\infty}{\infty}\), \(\frac{0}{0}\).` },
    'apis-c4-18': { q: r`By comparative growth, \(\displaystyle\lim_{n \to +\infty} \frac{n^2}{e^n}\) equals:`,
      o: [r`0`, r`\(+\infty\)`, r`1`, r`\(\dfrac{2}{e}\)`],
      x: r`The exponential beats any power of \(n\), which beats the logarithm: \(\frac{n^\alpha}{e^n} \to 0\) and \(\frac{\ln n}{n} \to 0\). Results to quote as they are.` },
    'apis-c4-19': { q: r`What is \(\displaystyle\lim_{n \to +\infty} \frac{e^n - n^2}{n + \ln(n)}\)?`,
      o: [r`\(+\infty\)`, r`0`, r`1`, r`\(-\infty\)`],
      x: r`Factor out the dominant term: \(\frac{e^n}{n} \times \frac{1 - \frac{n^2}{e^n}}{1 + \frac{\ln n}{n}}\). The second factor tends to 1 and \(\frac{e^n}{n} \to +\infty\) (Moodle model exercise).` },
    'apis-c4-20': { q: r`The squeeze theorem: if, from some rank onwards, \(u_n \leq v_n \leq w_n\), then \((v_n)\) converges to \(\ell\) as soon as:`,
      o: [r`\((u_n)\) and \((w_n)\) converge to the same real number \(\ell\)`, r`\((u_n)\) and \((w_n)\) converge`, r`\((u_n)\) converges to \(\ell\)`, r`\((u_n)\) and \((w_n)\) are bounded`],
      x: r`The two sequences on either side must have the <b>same</b> limit. With two different limits, \((v_n)\) may fail to converge: \(-1 \leq (-1)^n \leq 1\). Statement and proof asked in the January 2024 exam (5 points).` },
    'apis-c4-21': { q: r`What is \(\displaystyle\lim_{n \to +\infty} \frac{2n + (-1)^n}{n^2 + \cos(n)}\)?`,
      o: [r`0`, r`2`, r`it does not exist, because of \((-1)^n\)`, r`\(+\infty\)`],
      x: r`For \(n \geq 2\): \(\frac{2n - 1}{n^2 + 1} \leq u_n \leq \frac{2n + 1}{n^2 - 1}\), and both bounds tend to 0. By the squeeze theorem, \(u_n \to 0\) (Moodle model exercise). The oscillating terms are bounded: they weigh nothing next to \(n\) and \(n^2\).` },
    'apis-c4-22': { q: r`Every convergent sequence is bounded.`,
      x: r`True, and the proof is one to know (asked in the January 2023 and January 2025 exams): with \(\varepsilon = 1\), there is \(N\) such that \(|u_n| \lt 1 + |\ell|\) for \(n \geq N\); set \(M = \max(|u_0|, \ldots, |u_{N-1}|, 1 + |\ell|)\).` },
    'apis-c4-23': { q: r`Every bounded sequence is convergent.`,
      x: r`False: \(((-1)^n)\) is bounded by 1 and does not converge. This is the (false) converse of the theorem “convergent \(\Rightarrow\) bounded”. Its contrapositive, however, is true: an unbounded sequence diverges.` },
    'apis-c4-24': { q: r`The sequence \((q^n)\), with \(q\) a real number, converges if and only if:`,
      o: [r`\(-1 \lt q \leq 1\)`, r`\(-1 \leq q \leq 1\)`, r`\(0 \leq q \lt 1\)`, r`\(q \lt 1\)`],
      x: r`If \(|q| \lt 1\), \(q^n \to 0\); if \(q = 1\), the sequence is constant equal to 1; if \(q \gt 1\), \(q^n \to +\infty\); if \(q \leq -1\), no limit (for \(q = -1\): \(1, -1, 1\ldots\)). Question from the December 2022 course test.` },
    'apis-c4-25': { q: r`For \(q \neq 1\), \(\displaystyle\sum_{k=0}^{n} q^k = \)`,
      o: [r`\(\dfrac{1 - q^{n+1}}{1 - q}\)`, r`\(\dfrac{1 - q^{n}}{1 - q}\)`, r`\(\dfrac{1 - q^{n+1}}{1 + q}\)`, r`\((n+1)\,q^n\)`],
      x: r`There are \(n + 1\) terms, hence the exponent \(n + 1\). For \(q = 1\), the sum is \(n + 1\). For a geometric sequence: first term \(\times \frac{1 - q^{\text{number of terms}}}{1 - q}\).` },
    'apis-c4-26': { q: r`The sequence \(w_n = \left(-\dfrac{2}{3}\right)^n\) (November 2023 course test):`,
      o: [r`converges to 0`, r`has no limit, because its sign alternates`, r`tends to \(-\infty\)`, r`converges to \(-\dfrac{2}{3}\)`],
      x: r`Geometric sequence with common ratio \(q = -\frac{2}{3}\), with \(|q| \lt 1\): it converges to 0. The sign alternates, but \(|w_n| = \left(\frac{2}{3}\right)^n \to 0\).` },
    'apis-c4-27': { q: r`For \(u_{n+1} = \dfrac{u_n + 4}{5}\) (Tutorial 4), the sequence is constant if and only if \(u_0\) equals:`,
      o: [r`1`, r`4`, r`\(\dfrac{4}{5}\)`, r`0`],
      x: r`Solve \(\ell = \frac{\ell + 4}{5}\): \(5\ell = \ell + 4\), \(\ell = 1\). This is the fixed-point equation; it is this \(\ell\) that you subtract to get a geometric sequence.` },
    'apis-c4-28': { q: r`Still for \(u_{n+1} = \dfrac{u_n + 4}{5}\), with \(u_0 = 5\): the sequence \(v_n = u_n - 1\) is geometric with common ratio \(\frac{1}{5}\), so:`,
      o: [r`\(u_n = 1 + \dfrac{4}{5^n}\), which tends to 1`, r`\(u_n = \dfrac{5}{5^n}\), which tends to 0`, r`\(u_n = 1 + \dfrac{5}{5^n}\), which tends to 1`, r`\(u_n = 4 + \dfrac{1}{5^n}\), which tends to 4`],
      x: r`\(v_0 = u_0 - 1 = 4\), so \(v_n = \frac{4}{5^n}\) and \(u_n = 1 + \frac{4}{5^n}\). Check: \(u_1 = \frac{9}{5} = 1 + \frac{4}{5}\). The limit is the fixed point.` },
    'apis-c4-29': { q: r`\(u_n = 0.11\ldots1\) (with \(n\) digits 1 after the decimal point). The sequence \((u_n)\) converges to:`,
      o: [r`\(\dfrac{1}{9}\)`, r`\(\dfrac{1}{10}\)`, r`\(0.2\)`, r`\(\dfrac{11}{100}\)`],
      x: r`\(u_n = \displaystyle\sum_{k=1}^{n} 10^{-k} = \frac{1}{10}\cdot\frac{1 - 10^{-n}}{1 - \frac{1}{10}} = \frac{1 - 10^{-n}}{9} \to \frac{1}{9}\) (Moodle model exercise).` },
    'apis-c4-30': { q: r`Let \((u_n)\) be a sequence of nonzero real numbers. If there exists \(\ell\) such that, from some rank onwards, \(\left|\dfrac{u_{n+1}}{u_n}\right| \lt \ell \lt 1\), then:`,
      o: [r`\(u_n \to 0\)`, r`\(u_n \to \ell\)`, r`\((u_n)\) is geometric`, r`\((u_n)\) is increasing`],
      x: r`Theorem from the “Remarkable examples” sheet: the sequence decreases in absolute value at least as fast as a geometric sequence with common ratio \(\ell \lt 1\). Corollary: if \(\frac{u_{n+1}}{u_n} \to 0\), then \(u_n \to 0\).` },
    'apis-c4-31': { q: r`For \(u_n = \dfrac{3^n (n!)^2}{(2n)!}\), we find \(\dfrac{u_{n+1}}{u_n} = \dfrac{3(n+1)}{2(2n+1)}\). We deduce:`,
      o: [r`the ratio tends to \(\frac{3}{4} \lt 1\), so \(u_n \to 0\)`, r`the ratio tends to \(\frac{3}{4}\), so \(u_n \to \frac{3}{4}\)`, r`the ratio is smaller than 1, so the sequence is increasing`, r`the ratio tends to \(\frac{3}{2}\), so \(u_n \to +\infty\)`],
      x: r`\(\frac{3(n+1)}{2(2n+1)} \to \frac{3}{4}\): from some rank onwards (\(n \gt 7\)) the ratio is less than \(\frac{4}{5} \lt 1\), and the criterion gives \(u_n \to 0\) (Moodle model exercise). The limit of the ratio is not the limit of the sequence.` },
    'apis-c4-32': { q: r`Which of these sequences tends to \(+\infty\) without being increasing (Tutorial 4, classic counterexamples)?`,
      o: [r`\(u_n = n + 2(-1)^n\)`, r`\(u_n = n^2\)`, r`\(u_n = (-1)^n\,n\)`, r`\(u_n = \dfrac{1}{n+1}\)`],
      x: r`\(u_n \geq n - 2 \to +\infty\), but \(u_2 = 4\) and \(u_3 = 1\): the sequence drops at every odd rank. \(((-1)^n n)\) has no limit: it is neither bounded above nor bounded below.` },
    'apis-c5-01': { q: r`An increasing sequence that is bounded above…`,
      o: [r`converges`, r`tends to its upper bound`, r`tends to \(+\infty\)`, r`is constant from some rank on`],
      x: r`Monotone convergence theorem: every increasing sequence that is bounded above is convergent. The theorem does not give the limit: it is only less than or equal to every upper bound.` },
    'apis-c5-02': { q: r`If \((u_n)\) is increasing and bounded above by 3, then its limit is 3.`,
      x: r`The sequence converges to a real number \(\ell \leq 3\), not necessarily 3. Example: \(u_n = 1 - \frac{1}{n+1}\) is increasing, bounded above by 3, and tends to 1.` },
    'apis-c5-03': { q: r`\((u_n)\) is increasing and not bounded above. Then…`,
      o: [r`\(u_n \to +\infty\)`, r`\((u_n)\) converges`, r`\((u_n)\) has no limit`, r`\((u_n)\) is bounded`],
      x: r`A monotonic sequence always has a limit, finite or infinite. Increasing and bounded above: it converges. Increasing and not bounded above: it tends to \(+\infty\).` },
    'apis-c5-04': { q: r`\((u_n)\) and \((v_n)\) are adjacent if…`,
      o: [r`\((u_n)\) is increasing, \((v_n)\) is decreasing and \(\lim (v_n - u_n) = 0\)`, r`\((u_n)\) is increasing, \((v_n)\) is decreasing and \(u_n \leq v_n\)`, r`they converge to the same limit`, r`they are both increasing and \(\lim (v_n - u_n) = 0\)`],
      x: r`Three conditions: one increasing, one decreasing, difference with limit zero. “Same limit” is the conclusion of the theorem, not the definition; \(u_n \leq v_n\) is a consequence.` },
    'apis-c5-05': { q: r`January 2024 exam: \(u_n = \displaystyle\sum_{k=0}^{n} \frac{1}{k!}\) and \(v_n = u_n + \dfrac{1}{n!}\). What is \(v_{n+1} - v_n\)?`,
      o: [r`\(\dfrac{1 - n}{(n+1)!}\)`, r`\(\dfrac{1}{(n+1)!}\)`, r`\(-\dfrac{1}{n!}\)`, r`\(\dfrac{n - 1}{(n+1)!}\)`],
      x: r`\(v_{n+1} - v_n = \dfrac{1}{(n+1)!} + \dfrac{1}{(n+1)!} - \dfrac{1}{n!} = \dfrac{2 - (n+1)}{(n+1)!} = \dfrac{1 - n}{(n+1)!}\), negative for \(n \geq 2\): \((v_n)\) is decreasing.` },
    'apis-c5-06': { q: r`\((u_n)\) increasing and \((v_n)\) decreasing are adjacent, with common limit \(\ell\). For every \(n\):`,
      o: [r`\(u_n \leq \ell \leq v_n\)`, r`\(v_n \leq \ell \leq u_n\)`, r`\(u_n \leq v_n \leq \ell\)`, r`\(\ell \leq u_n \leq v_n\)`],
      x: r`The theorem gives \(u_n \leq u_{n+1} \leq \ell \leq v_{n+1} \leq v_n\): the limit is bracketed, with an error of at most \(v_n - u_n\).` },
    'apis-c5-07': { q: r`Which of these statements is equivalent to “\(u_n \to \ell\)”?`,
      o: [r`\(u_{2n} \to \ell\) and \(u_{2n+1} \to \ell\)`, r`\(u_{2n} \to \ell\)`, r`\(u_{3n} \to \ell\) and \(u_{3n+1} \to \ell\)`, r`a subsequence of \((u_n)\) converges to \(\ell\)`],
      x: r`Even and odd ranks cover all ranks (Tutorial 4, exercise 4.10). With \(3n\) and \(3n + 1\), the ranks \(3n + 2\) are not covered.` },
    'apis-c5-08': { q: r`January 2025 exam: why does the sequence \(u_n = \sin\left(\dfrac{n\pi}{3}\right)\) diverge?`,
      o: [r`\(u_{3n} \to 0\) and \(u_{6n+1} \to \dfrac{\sqrt{3}}{2}\): two subsequences with different limits`, r`it is not bounded`, r`it is not monotonic`, r`\(u_{3n} = 0\) for every \(n\)`],
      x: r`If a sequence converges to \(\ell\), all its subsequences converge to \(\ell\). Two subsequences with different limits: the sequence diverges. Not being monotonic proves nothing.` },
    'apis-c5-09': { q: r`If \((u_{2n})\) converges, then \((u_n)\) converges.`,
      x: r`Counterexample: \(u_n = (-1)^n\). \((u_{2n})\) is constant equal to 1, but \((u_n)\) diverges. You also need \((u_{2n+1})\), with the same limit.` },
    'apis-c5-10': { q: r`The Bolzano-Weierstrass theorem states that…`,
      o: [r`from every bounded sequence, you can extract a convergent subsequence`, r`every bounded sequence converges`, r`every convergent sequence is bounded`, r`every monotonic and bounded sequence converges`],
      x: r`It speaks of <b>one</b> subsequence. “Bounded, hence convergent” is false: \(((-1)^n)\).` },
    'apis-c5-11': { q: r`The sequence \((\cos(n))\) has a convergent subsequence.`,
      x: r`It is bounded (\(|\cos(n)| \leq 1\)): Bolzano-Weierstrass applies, even if we cannot write the subsequence down.` },
    'apis-c5-12': { q: r`January 2025 exam: \(u_{n+1} = \dfrac{3u_n + 2v_n}{5}\), \(v_{n+1} = \dfrac{2u_n + 3v_n}{5}\). The sequence \(w_n = v_n - u_n\) is geometric with common ratio…`,
      o: [r`\(\dfrac{1}{5}\)`, r`\(5\)`, r`\(\dfrac{2}{5}\)`, r`\(\dfrac{3}{5}\)`],
      x: r`\(w_{n+1} = \dfrac{2u_n + 3v_n - 3u_n - 2v_n}{5} = \dfrac{v_n - u_n}{5} = \dfrac{1}{5}w_n\). Since \(w_0 = 1\), \(w_n = \dfrac{1}{5^n} \gt 0\), which gives both monotonicities.` },
    'apis-c5-13': { q: r`January 2025 exam: \(u_n = \displaystyle\sum_{k=n}^{2n-1} \frac{1}{k}\). What is \(u_{n+1} - u_n\)?`,
      o: [r`\(\dfrac{1}{2n+1} - \dfrac{1}{2n}\)`, r`\(\dfrac{1}{2n} + \dfrac{1}{2n+1}\)`, r`\(\dfrac{1}{2n+1} - \dfrac{1}{n}\)`, r`\(-\dfrac{1}{n}\)`],
      x: r`\(u_{n+1}\) runs from \(k = n + 1\) to \(2n + 1\): two terms come in (\(\frac{1}{2n}\), \(\frac{1}{2n+1}\)), one goes out (\(\frac{1}{n}\)). \(\frac{1}{2n} + \frac{1}{2n+1} - \frac{1}{n} = \frac{1}{2n+1} - \frac{1}{2n} \lt 0\): decreasing.` },
    'apis-c6-01': { q: r`“The interval \(I\) is stable under \(f\)” means…`,
      o: [r`\(f(I) \subset I\)`, r`\(I \subset f(I)\)`, r`\(f\) is increasing on \(I\)`, r`\(f\) has a fixed point in \(I\)`],
      x: r`For every \(x \in I\), \(f(x) \in I\). Then, if \(u_0 \in I\), all the \(u_n\) are in \(I\) (by induction): the sequence is well defined.` },
    'apis-c6-02': { q: r`\(u_{n+1} = u_n^2\) and \(u_0 = 0.8\) (Tutorial 4, exercise 6.15). The sequence…`,
      o: [r`decreases and tends to 0`, r`increases and tends to 1`, r`increases and tends to \(+\infty\)`, r`is constant`],
      x: r`\(0.8\); \(0.64\); \(0.4096\)… On \(]0, 1[\), \(x^2 \lt x\). \(f\) is increasing on \([0, 1]\) and yet the sequence decreases: \(f\) increasing only gives a monotonic sequence.` },
    'apis-c6-03': { q: r`\(u_{n+1} = f(u_n)\) with \(f\) continuous on \(I\) and \(u_0 \in I\). Which of these statements is true (Tutorial 4, exercise 6.15)?`,
      o: [r`If \((u_n)\) converges to a real number \(\ell \in I\), then \(\ell = f(\ell)\)`, r`If \(\ell = f(\ell)\), then \((u_n)\) converges to \(\ell\)`, r`\((u_n)\) converges if and only if \(f\) has a fixed point`, r`If \(f\) is increasing, then \((u_n)\) is increasing`],
      x: r`Fixed points are the only <b>possible</b> limits. Their existence does not prove convergence: \(f(x) = x^2\) has fixed points 0 and 1, and the sequence tends to \(+\infty\) for \(u_0 = 1.3\).` },
    'apis-c6-04': { q: r`January 2024 exam: \(u_{n+1} = \dfrac{u_n}{u_n + 8}\) with \(u_n \gt 0\) for every \(n\). If the sequence converges, its limit is…`,
      o: [r`\(0\)`, r`\(-7\)`, r`\(\dfrac{1}{8}\)`, r`\(1\)`],
      x: r`\(\ell = \dfrac{\ell}{\ell + 8} \iff \ell(\ell + 7) = 0\): 0 or \(-7\). Since \(u_n \gt 0\), \(\ell \geq 0\): only \(\ell = 0\) remains.` },
    'apis-c6-05': { q: r`\(f\) is increasing on a stable interval \(I\), \(u_0 \in I\) and \(u_1 \leq u_0\). Then \((u_n)\) is…`,
      o: [r`decreasing`, r`increasing`, r`constant`, r`neither increasing nor decreasing`],
      x: r`By induction: if \(u_{n+1} \leq u_n\), then \(f(u_{n+1}) \leq f(u_n)\), that is \(u_{n+2} \leq u_{n+1}\). The order of the first two terms propagates.` },
    'apis-c6-06': { q: r`January 2025 exam: \(u_{n+1} = 1 + \dfrac{1}{4}u_n^2\). Factorising, \(u_{n+1} - u_n =\)`,
      o: [r`\(\dfrac{(u_n - 2)^2}{4}\)`, r`\(\dfrac{(u_n - 2)(u_n + 2)}{4}\)`, r`\(\dfrac{(u_n - 1)^2}{4}\)`, r`\(-\dfrac{(u_n - 2)^2}{4}\)`],
      x: r`\(\dfrac{u_n^2}{4} - u_n + 1 = \dfrac{u_n^2 - 4u_n + 4}{4} = \dfrac{(u_n - 2)^2}{4} \geq 0\): the sequence is increasing.` },
    'apis-c6-07': { q: r`What are the fixed points of \(f(x) = \dfrac{x^2 + 3}{4}\) (Tutorial 4, exercise 6.16)?`,
      o: [r`1 and 3`, r`0 and 3`, r`\(-1\) and 3`, r`1 only`],
      x: r`\(\dfrac{x^2 + 3}{4} = x \iff x^2 - 4x + 3 = 0 \iff (x - 1)(x - 3) = 0\).` },
    'apis-c6-08': { q: r`\(u_{n+1} = \dfrac{u_n^2 + 3}{4}\) and \(u_0 = 2\). The sequence tends to…`,
      o: [r`\(1\)`, r`\(3\)`, r`\(+\infty\)`, r`\(2\)`],
      x: r`On \(]1, 3[\) (stable), \(u_{n+1} - u_n = \dfrac{(u_n - 1)(u_n - 3)}{4} \lt 0\): decreasing, bounded below by 1, hence convergent to a fixed point \(\ell \leq u_0 \lt 3\). So \(\ell = 1\).` },
    'apis-c6-09': { q: r`Heron’s method: \(u_{n+1} = \dfrac{1}{2}\left(u_n + \dfrac{a}{u_n}\right)\), \(a \gt 0\), \(u_0 \gt 0\). The sequence converges to…`,
      o: [r`\(\sqrt{a}\)`, r`\(a\)`, r`\(\dfrac{a}{2}\)`, r`\(0\)`],
      x: r`Fixed point: \(x = \dfrac{1}{2}\left(x + \dfrac{a}{x}\right) \iff x^2 = a\). The sequence is decreasing from rank 1 on and bounded below by \(\sqrt{a}\).` },
    'apis-c6-10': { q: r`January 2024 exam: \(v_n = 1 + \dfrac{7}{u_n}\) is geometric with common ratio 8, with \(v_0 = 8\). Then \(u_n =\)`,
      o: [r`\(\dfrac{7}{8^{n+1} - 1}\)`, r`\(\dfrac{7}{8^n}\)`, r`\(8^{n+1} - 1\)`, r`\(\dfrac{7}{8^n - 1}\)`],
      x: r`\(v_n = 8 \times 8^n = 8^{n+1}\), and \(v_n - 1 = \dfrac{7}{u_n}\) gives \(u_n = \dfrac{7}{v_n - 1}\). We recover \(u_n \to 0\).` },
    'apis-c7-01': { q: r`For \((v_n)\) with non-zero terms, \(u_n = o(v_n)\) is equivalent to…`,
      o: [r`\(\dfrac{u_n}{v_n} \to 0\)`, r`\(\dfrac{u_n}{v_n} \to 1\)`, r`\(\left(\dfrac{u_n}{v_n}\right)\) is bounded`, r`\(\dfrac{u_n}{v_n} \to +\infty\)`],
      x: r`Negligible: the quotient tends to 0. Limit 1: equivalent. Bounded quotient: dominated.` },
    'apis-c7-02': { q: r`For \((v_n)\) with non-zero terms, \(u_n \sim v_n\) is equivalent to…`,
      o: [r`\(\dfrac{u_n}{v_n} \to 1\)`, r`\(u_n - v_n \to 0\)`, r`\((u_n)\) and \((v_n)\) have the same limit`, r`\(\left(\dfrac{u_n}{v_n}\right)\) is bounded`],
      x: r`Equivalence compares quotients. \(n + 1 \sim n\) although the difference is 1; \(\frac{1}{n}\) and \(\frac{1}{n^2}\) have the same limit without being equivalent.` },
    'apis-c7-03': { q: r`\(n\sin(n) = O(n)\).`,
      x: r`\(\dfrac{n\sin(n)}{n} = \sin(n)\) is bounded. However it is neither an \(o(n)\) nor an equivalent: \(\sin(n)\) has no limit.` },
    'apis-c7-04': { q: r`\(u_n = o(1)\) means that…`,
      o: [r`\(u_n \to 0\)`, r`\((u_n)\) is bounded`, r`\((u_n)\) is zero from some rank on`, r`\(u_n \to 1\)`],
      x: r`\(u_n = \varepsilon_n \times 1\) with \(\varepsilon_n \to 0\). “Bounded” is written \(u_n = O(1)\); “zero from some rank on” is written \(u_n \sim 0\).` },
    'apis-c7-05': { q: r`\(u_n \sim v_n\) is equivalent to \(u_n - v_n \to 0\).`,
      x: r`False in both directions (Tutorial 4, exercise 5.14). \(n + 1 \sim n\) but the difference is 1. \(\frac{1}{n} - \frac{1}{n^2} \to 0\) but the quotient is \(n\). The correct notation: \(u_n = v_n + o(v_n)\).` },
    'apis-c7-06': { q: r`Which ranking is correct?`,
      o: [r`\(\ln(n) \ll n \ll n\ln(n) \ll n^2\)`, r`\(\ln(n) \ll n \ll n^2 \ll n\ln(n)\)`, r`\(n \ll \ln(n) \ll n\ln(n) \ll n^2\)`, r`\(\ln(n) \ll n\ln(n) \ll n \ll n^2\)`],
      x: r`\(\dfrac{n}{n\ln n} = \dfrac{1}{\ln n} \to 0\) and \(\dfrac{n\ln n}{n^2} = \dfrac{\ln n}{n} \to 0\): \(n\ln(n)\) lies between \(n\) and \(n^2\).` },
    'apis-c7-07': { q: r`Which of these sequences is negligible compared with \(\dfrac{1}{n}\)?`,
      o: [r`\(\dfrac{1}{n^2}\)`, r`\(\dfrac{1}{\ln(n)}\)`, r`\(\dfrac{\ln(n)}{n}\)`, r`\(\dfrac{1}{\sqrt{n}}\)`],
      x: r`\(\dfrac{1/n^2}{1/n} = \dfrac{1}{n} \to 0\). The other three quotients (\(\frac{n}{\ln n}\), \(\ln n\), \(\sqrt{n}\)) tend to \(+\infty\): it is \(\frac{1}{n}\) that is negligible compared with them.` },
    'apis-c7-08': { q: r`\(2^n = o(3^n)\).`,
      x: r`\(\dfrac{2^n}{3^n} = \left(\dfrac{2}{3}\right)^n \to 0\) because \(\left|\frac{2}{3}\right| \lt 1\).` },
    'apis-c7-09': { q: r`A simple equivalent of \(\ln(n) + 2n - 3\) is…`,
      o: [r`\(2n\)`, r`\(\ln(n)\)`, r`\(2n - 3\)`, r`\(n\)`],
      x: r`\(\ln(n) = o(n)\) and \(3 = o(n)\): keep the dominant term, with its coefficient. \(2n - 3\) is also equivalent, but it is not “simple”; \(n\) does not work (quotient 2).` },
    'apis-c7-10': { q: r`A simple equivalent of \(\dfrac{1}{n - 1} - \dfrac{1}{n + 1}\) is…`,
      o: [r`\(\dfrac{2}{n^2}\)`, r`\(0\)`, r`\(\dfrac{1}{n}\)`, r`\(\dfrac{2}{n}\)`],
      x: r`Reduce first: \(\dfrac{1}{n-1} - \dfrac{1}{n+1} = \dfrac{2}{n^2 - 1} \sim \dfrac{2}{n^2}\). Subtracting the equivalents \(\frac{1}{n} - \frac{1}{n}\) would give 0: forbidden.` },
    'apis-c7-11': { q: r`If \(u_n \sim v_n\) and \(w_n \sim x_n\), then \(u_n + w_n \sim v_n + x_n\).`,
      x: r`Equivalents carry over to products, quotients and powers, not to sums. \(n + 1 \sim n\) and \(-n \sim -n\), but \(1\) is not equivalent to \(0\).` },
    'apis-c7-12': { q: r`January 2025 exam: \(u_n = 3n + 6\) and \(v_n = 5n - 1\). All the possible comparisons are…`,
      o: [r`\(u_n = O(v_n)\) and \(v_n = O(u_n)\), nothing else`, r`\(u_n \sim v_n\)`, r`\(u_n = o(v_n)\)`, r`\(v_n = o(u_n)\)`],
      x: r`\(\dfrac{u_n}{v_n} \to \dfrac{3}{5}\): the quotient converges to a non-zero real number, so it is bounded in both directions. No equivalence (\(\frac{3}{5} \neq 1\)), no negligibility.` },
    'apis-c7-13': { q: r`January 2024 exam: \(u_n = 4^n + 1\) and \(v_n = 5^n\). You must state…`,
      o: [r`\(u_n = o(v_n)\) and \(u_n = O(v_n)\)`, r`\(u_n \sim v_n\)`, r`\(v_n = o(u_n)\)`, r`only \(u_n = O(v_n)\)`],
      x: r`\(\dfrac{u_n}{v_n} = \left(\dfrac{4}{5}\right)^n + \dfrac{1}{5^n} \to 0\): \(u_n = o(v_n)\). The quotient converges, so it is bounded: \(u_n = O(v_n)\) as well. “State all the possible comparisons”.` }
  });
})();
